import { Ionicons } from "@expo/vector-icons"; import { router } from "expo-router"; import * as Linking from "expo-linking"; import { useCallback,useEffect,useState } from "react"; import { ActivityIndicator,Pressable,RefreshControl,ScrollView,StyleSheet,Text,View } from "react-native"; import { api } from "@/lib/api"; import { theme,money } from "@/lib/theme";
export default function VendorDashboard(){const [orders,setOrders]=useState<any[]>([]);const [loading,setLoading]=useState(true);const [refreshing,setRefreshing]=useState(false);const load=useCallback(async(r=false)=>{r?setRefreshing(true):setLoading(true);try{const x=await api<any>("/api/orders/vendor/me",{auth:true});setOrders(Array.isArray(x)?x:x.orders??x.items??[])}catch{}finally{setLoading(false);setRefreshing(false)}},[]);useEffect(()=>{load()},[load]);const total=orders.reduce((s,o)=>s+Number(o.order?.totalAmount??o.total??0),0);return <View style={styles.screen}><View style={styles.header}><Pressable onPress={()=>router.back()}><Ionicons name="arrow-back" size={21} color={theme.colors.graphite950}/></Pressable><View style={{flex:1,marginLeft:13}}><Text style={styles.kicker}>TTFL STORE</Text><Text style={styles.title}>Vendor dashboard</Text></View><Pressable onPress={()=>Linking.openURL("https://www.ttflstore.name.ng/vendor/dashboard")}><Ionicons name="open-outline" size={19} color={theme.colors.graphite950}/></Pressable></View><ScrollView refreshControl={<RefreshControl refreshing={refreshing} onRefresh={()=>load(true)}/>} contentContainerStyle={styles.content}><View style={styles.stats}><View><Text style={styles.statLabel}>ORDERS</Text><Text style={styles.statValue}>{orders.length}</Text></View><View><Text style={styles.statLabel}>ORDER VALUE</Text><Text style={styles.statValue}>{money(total)}</Text></View></View><View style={styles.quick}><Quick icon="add-circle-outline" title="Add product" onPress={()=>Linking.openURL("https://www.ttflstore.name.ng/vendor/products/new")}/><Quick icon="storefront-outline" title="Storefront" onPress={()=>Linking.openURL("https://www.ttflstore.name.ng/vendor/store")}/><Quick icon="bar-chart-outline" title="Analytics" onPress={()=>Linking.openURL("https://www.ttflstore.name.ng/vendor/analytics")}/></View><Text style={styles.section}>RECENT ORDERS</Text>{loading?<ActivityIndicator color={theme.colors.ember600}/>:orders.length?orders.slice(0,20).map((o:any)=>{const order=o.order??o;return <Pressable key={o.id??order.orderNumber} style={styles.order} onPress={()=>router.push({pathname:"/orders/[orderNumber]",params:{orderNumber:order.orderNumber}})}><View style={styles.orderIcon}><Ionicons name="cube-outline" size={18} color={theme.colors.graphite950}/></View><View style={styles.orderCopy}><Text style={styles.orderNumber}>{order.orderNumber}</Text><Text style={styles.orderMeta}>{o.status??order.status??"PROCESSING"} · {order.createdAt?new Date(order.createdAt).toLocaleDateString():""}</Text></View><Text style={styles.orderTotal}>{money(o.subtotal??order.totalAmount??0)}</Text></Pressable>}):<Text style={styles.empty}>No vendor orders yet.</Text>}<Pressable onPress={()=>Linking.openURL("https://www.ttflstore.name.ng/vendor/dashboard")} style={styles.web}><Text style={styles.webText}>Open full vendor dashboard</Text><Ionicons name="arrow-forward" size={16} color="#fff"/></Pressable></ScrollView></View>}
function Quick({icon,title,onPress}:{icon:keyof typeof Ionicons.glyphMap;title:string;onPress:()=>void}){return <Pressable onPress={onPress} style={styles.quickItem}><Ionicons name={icon} size={20} color={theme.colors.ember600}/><Text style={styles.quickText}>{title}</Text></Pressable>}
const styles=StyleSheet.create({screen:{flex:1,backgroundColor:theme.colors.cloud50},header:{height:84,padding:18,paddingTop:27,backgroundColor:"#fff",borderBottomWidth:1,borderBottomColor:theme.colors.graphite200,flexDirection:"row",alignItems:"center"},kicker:{fontSize:9,fontWeight:"900",letterSpacing:1.4,color:theme.colors.ember600},title:{fontSize:20,fontWeight:"900",color:theme.colors.graphite950,marginTop:2},content:{padding:14,paddingBottom:40},stats:{backgroundColor:theme.colors.graphite950,borderRadius:16,padding:18,flexDirection:"row",gap:40},statLabel:{fontSize:8,fontWeight:"900",letterSpacing:1.2,color:theme.colors.graphite300},statValue:{fontSize:22,fontWeight:"900",color:"#fff",marginTop:5},quick:{flexDirection:"row",gap:8,marginTop:10},quickItem:{flex:1,minHeight:76,backgroundColor:"#fff",borderWidth:1,borderColor:theme.colors.graphite200,borderRadius:14,padding:11,justifyContent:"center"},quickText:{fontSize:11,fontWeight:"800",color:theme.colors.graphite950,marginTop:6},section:{fontSize:9,fontWeight:"900",letterSpacing:1.4,color:theme.colors.graphite600,marginTop:24,marginBottom:8},order:{backgroundColor:"#fff",borderWidth:1,borderColor:theme.colors.graphite200,borderRadius:14,padding:12,flexDirection:"row",alignItems:"center",marginBottom:8},orderIcon:{width:38,height:38,borderRadius:11,backgroundColor:theme.colors.cloud100,alignItems:"center",justifyContent:"center"},orderCopy:{flex:1,marginLeft:10},orderNumber:{fontSize:13,fontWeight:"900",color:theme.colors.graphite950},orderMeta:{fontSize:9.5,color:theme.colors.graphite600,marginTop:4},orderTotal:{fontSize:12,fontWeight:"900",color:theme.colors.graphite950},empty:{textAlign:"center",color:theme.colors.graphite600,padding:30},web:{height:48,borderRadius:10,backgroundColor:theme.colors.ember600,flexDirection:"row",alignItems:"center",justifyContent:"center",gap:8,marginTop:14},webText:{color:"#fff",fontWeight:"900",fontSize:12}});
